script:
$env:Path += ";C:\Users\E\AppData\Local\hermes\bin"
"=== trying providers dict format ==="
hermes config set providers.zen.base_url "https://opencode.ai/zen/v1" 2>&1 | Select-Object -First 2
hermes config set providers.zen.key_env "ZEN_API_KEY" 2>&1 | Select-Object -First 2
hermes config set providers.zen.name "OpenCode Zen" 2>&1 | Select-Object -First 2
"=== testing ==="
$job = Start-Job -ScriptBlock {
  $env:Path += ";C:\Users\E\AppData\Local\hermes\bin"
  hermes -z "Say HI" -m "space-bunny-free" --provider zen 2>&1 | Select-Object -First 10
}
if (Wait-Job $job -Timeout 60) {
  Receive-Job $job | Select-Object -First 10
} else {
  "TIMED OUT"
  Stop-Job $job
}
Remove-Job $job -Force
